flowchart TD
    State0["0b000 (0 bits set)\nCount = EVEN\nEncryption: OFF\n(Factory Default)"]
    State1["0b001 (1 bit set)\nCount = ODD\nEncryption: ON\n(Where I was stuck!)"]
    State2["0b011 (2 bits set)\nCount = EVEN\nEncryption: OFF\n(The Escape Hatch!)"]
    State3["0b111 (3 bits set)\nCount = ODD\nEncryption: ON\n(Permanent Release Mode)"]

    State0 -->|"Burn 1st bit (Bootloader)"| State1
    State1 -->|"Burn 2nd bit (Recovery!)"| State2
    State2 -->|"Burn 3rd bit (No return)"| State3

    classDef normal fill:#161b22,stroke:#30363d,stroke-width:1px,color:#c9d1d9;
    classDef warning fill:#2d1b00,stroke:#d29922,stroke-width:2px,color:#f0883e;
    classDef success fill:#04260f,stroke:#238636,stroke-width:2px,color:#3fb950;
    classDef danger fill:#3d0808,stroke:#f85149,stroke-width:2px,color:#f85149;

    class State0 normal;
    class State1 warning;
    class State2 success;
    class State3 danger;

void setup() {
    Serial.begin(115200);
}

void loop() {
    Serial.printf("RECOVERY_OK uptime=%lu s flash=%u bytes encryption=OFF\n", 
                  millis() / 1000, ESP.getFlashChipSize());
    delay(1000);
}
